```js
await page.goto('/ops/rules');
await expect(page.getByRole('heading').first()).toBeVisible();

// Find the stylesheet rule that gives the admin label its 10px size (written as div.<class>)
const cls = await page.evaluate(() => {
  const found = [];
  const walk = (rules) => {
    for (const r of rules) {
      if (r.cssRules) walk(r.cssRules);
      if (r.selectorText && r.style && r.style.fontSize === '10px') found.push(r.selectorText);
    }
  };
  for (const sheet of document.styleSheets) {
    try { walk(sheet.cssRules); } catch (e) {}
  }
  for (const sel of found) {
    for (const part of sel.split(',')) {
      const m = part.trim().match(/div\.([\w-]*admin[\w-]*)\s*$/i);
      if (m) return m[1];
    }
  }
  for (const sel of found) {
    const m = sel.match(/div\.([\w-]+)/);
    if (m) return m[1];
  }
  return 'admin-label';
});

// Put a span carrying that class on the page
await page.evaluate((c) => {
  const s = document.createElement('span');
  s.id = 'repro-admin-label';
  s.className = c;
  s.textContent = 'Admin';
  document.body.appendChild(s);
}, cls);

await expect(page.locator('#repro-admin-label')).toBeVisible();
// Symptom: the span should get the same 10px size the div gets
await expect(page.locator('#repro-admin-label')).toHaveCSS('font-size', '10px');
